import{_ as s,o as e,c as i,a2 as t}from"./chunks/framework.D66Xq0Kv.js";const c=JSON.parse('{"title":"9. Parameters, Buffers, State, and Structural Members","description":"","frontmatter":{},"headers":[],"relativePath":"spec/09-parameters-state.md","filePath":"spec/09-parameters-state.md","lastUpdated":null}'),n={name:"spec/09-parameters-state.md"};function l(r,a,p,h,d,o){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="_9-parameters-buffers-state-and-structural-members" tabindex="-1">9. Parameters, Buffers, State, and Structural Members <a class="header-anchor" href="#_9-parameters-buffers-state-and-structural-members" aria-label="Permalink to &quot;9. Parameters, Buffers, State, and Structural Members&quot;">​</a></h1><h2 id="_9-1-param" tabindex="-1">9.1 <code>param</code> <a class="header-anchor" href="#_9-1-param" aria-label="Permalink to &quot;9.1 `param`&quot;">​</a></h2><p><code>param</code> declares an externally supplied parameter tensor:</p><div class="language-linnet vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">linnet</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">param</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> weight: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;">Tensor</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">Out</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">In</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">T</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">]</span></span></code></pre></div><p>A parameter declaration does not contain tensor payload data.</p><p>Optional parameters are permitted:</p><div class="language-linnet vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">linnet</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">param</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> bias: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;">Tensor</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">Out</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">T</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">]? </span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> none</span></span></code></pre></div><p>The default <code>none</code> means the parameter may be absent. A non-<code>none</code> tensor initializer for <code>param</code> is forbidden.</p><h2 id="_9-2-buffer" tabindex="-1">9.2 <code>buffer</code> <a class="header-anchor" href="#_9-2-buffer" aria-label="Permalink to &quot;9.2 `buffer`&quot;">​</a></h2><p><code>buffer</code> declares persistent non-parameter data such as statistics or fixed tables:</p><div class="language-linnet vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">linnet</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">buffer</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> running_mean: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;">Tensor</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">H</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;">f32</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">]</span></span></code></pre></div><p>Payload binding is external just like <code>param</code> unless a future specification explicitly defines generated constants.</p><p>Backends may map buffers to framework-specific non-trainable state.</p><h2 id="_9-3-state" tabindex="-1">9.3 <code>state</code> <a class="header-anchor" href="#_9-3-state" aria-label="Permalink to &quot;9.3 `state`&quot;">​</a></h2><p><code>state</code> declares mutable execution state owned by a block instance, such as a KV cache:</p><div class="language-linnet vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">linnet</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">state</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> cache: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;">Tensor</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">Batch</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">KvHeads</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">MaxSeq</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">Head</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">T</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">]</span></span></code></pre></div><p>A state member has a tensor type whose shape is fixed by the block&#39;s generics, like a <code>param</code>. It carries no payload: the runtime supplies the initial value (backends default to zeros) and keeps the latest value between entry calls.</p><p>Inside the block&#39;s functions and entries, the member name reads the current value, and an assignment statement replaces it:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>cache = updated</span></span></code></pre></div><p>The assigned value MUST have the declared type. Reads after an assignment observe it, in program order. A function may assign only state members of its own block; a parent block reads a child&#39;s state through its path (<code>layers[0].attention.cache</code>) but cannot assign it.</p><p>State flow is explicit. In Core IR every read and write is an operation on the block instance, ordered within its region, and each function records the state members it touches directly or through the functions it calls. The optimizer MUST NOT merge, remove, or reorder these operations relative to one another. Backends thread the values: a graph export takes the initial values as extra inputs and returns the final values as extra results, and a framework materializer keeps them as the module&#39;s non-trainable state, reset on request. Hidden global mutation is not permitted.</p><p>State members appear in the parameter manifest with kind <code>state</code>; weight files never contain them.</p><h2 id="_9-4-sub" tabindex="-1">9.4 <code>sub</code> <a class="header-anchor" href="#_9-4-sub" aria-label="Permalink to &quot;9.4 `sub`&quot;">​</a></h2><p><code>sub</code> declares structural child blocks:</p><div class="language-linnet vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">linnet</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">sub</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> norm: </span><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">RMSNorm</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">Hidden</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">T</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">sub</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> layers: [</span><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">DecoderLayer</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">Hidden</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">T</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">Layers</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">]</span></span></code></pre></div><h2 id="_9-5-parameter-paths" tabindex="-1">9.5 Parameter paths <a class="header-anchor" href="#_9-5-parameter-paths" aria-label="Permalink to &quot;9.5 Parameter paths&quot;">​</a></h2><p>A compiler instantiating a root block MUST derive deterministic hierarchical paths from sub-block and parameter names.</p><p>Example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>layers.0.attention.q_proj.weight</span></span></code></pre></div><p>These paths form the canonical parameter-manifest names unless a binding manifest maps them to external tensor names.</p><h2 id="_9-6-parameter-manifest" tabindex="-1">9.6 Parameter manifest <a class="header-anchor" href="#_9-6-parameter-manifest" aria-label="Permalink to &quot;9.6 Parameter manifest&quot;">​</a></h2><p>Semantic analysis of a fully instantiated root block can produce a parameter manifest containing at least:</p><ul><li>canonical path;</li><li>kind (<code>param</code>, <code>buffer</code>, or <code>state</code>);</li><li>tensor shape expression after known substitutions;</li><li>dtype;</li><li>optional/required status.</li></ul><p>This manifest is compiler data and contains no tensor bytes.</p>',34)])])}const u=s(n,[["render",l]]);export{c as __pageData,u as default};
